import numpy as np

def get_motion_data(doc, scope):
    motion_node = node_by_title(doc, f"{scope}: Motion log")
    if not motion_node: return []
    rows = table_rows(motion_node)
    data = []
    for _, row in rows:
        data.append({
            'frame': float(row['frame']),
            'object': row['object'],
            'x': float(row['x']), 'y': float(row['y']),
            'vx': float(row['vx']), 'vy': float(row['vy']),
            'speed': float(row['speed'])
        })
    return data

def get_obj_id_from_cell(cell):
    return f"Object {cell.split(' ')[0]}"

all_videos = [node['title'] for node in doc['nodes'] if node['title'].startswith('Video ')]
exits_info = []

for scope in all_videos:
    outcomes_list = outcomes(doc, scope)
    exit_events = [o for o in outcomes_list if o['kind'] == 'exit']
    if not exit_events:
        continue

    motion = get_motion_data(doc, scope)
    obj_motion = {}
    for m in motion:
        oid = get_obj_id_from_cell(m['object'])
        if oid not in obj_motion: obj_motion[oid] = []
        obj_motion[oid].append(m)

    for ev in exit_events:
        t_exit = ev['time']
        oid = ev['entities'][0]
        # Find the last frame recorded for this object in the motion log
        m_list = obj_motion.get(oid, [])
        if m_list:
            last_record = m_list[-1]
            exits_info.append({
                'scope': scope,
                'oid': oid,
                't_exit': t_exit,
                't_last': last_record['frame'],
                'x': last_record['x'],
                'y': last_record['y']
            })

for info in exits_info:
    print(f"{info['scope']} {info['oid']} Exit Event t={info['t_exit']}, Last Log t={info['t_last']} at ({info['x']:.2f}, {info['y']:.2f})")

if exits_info:
    max_coord = max(max(abs(i['x']), abs(i['y'])) for i in exits_info)
    print(f"Max absolute coordinate for last visible record: {max_coord:.2f}")
